from pathlib import Path
import json, datetime, hashlib
ROOT = Path(__file__).resolve().parents[1]

def save(name, obj):
    p = ROOT / name
    if p.exists():
        old = json.loads(p.read_text())
        assert {k: v for (k, v) in old.items() if k != 'frozen_at'} == obj, name + ' immutable contract mismatch'
        return
    obj = dict(obj, frozen_at=datetime.datetime.now(datetime.timezone.utc).isoformat())
    p.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + '\n')
